'use strict';

// MODULES //

var isOddf = require( '@stdlib/math/base/assert/is-oddf' );
var isInfinitef = require( '@stdlib/math/base/assert/is-infinitef' );
var isInteger = require( '@stdlib/math/base/assert/is-integer' );
var sqrtf = require( '@stdlib/math/base/special/sqrtf' );
var absf = require( '@stdlib/math/base/special/absf' );
var fromWordf = require( '@stdlib/number/float32/base/from-word' );
var toWordf = require( '@stdlib/number/float32/base/to-word' );
var float64ToFloat32 = require( '@stdlib/number/float64/base/to-float32' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var FLOAT32_ABS_MASK = require( '@stdlib/constants/float32/abs-mask' );
var xIsZero = require( './x_is_zero.js' );
var yIsInfinite = require( './y_is_infinite.js' );
var log2ax = require( './log2ax.js' );
var logx = require( './logx.js' );
var pow2 = require( './pow2.js' );


// VARIABLES //

// 0x3f7ffff8 = 1065353216 => 0 01111111011 11111111111111111000 => biased exponent: 126 = -1+127 => 2^-1 * (1.999999)
var HIGH_MAX_NEAR_UNITY = 0x3f7ffff8; // asm type annotation

// 0x4d000000 = 1291845632 => 0 10011010000 00000000000000000000 => biased exponent: 208 = 81+127 => 2^81
var HIGH_BIASED_EXP_27 = 0x4d000000; // asm type annotation

// 0x43000000 = 1124073472 => 0 10000110000 00000000000000000000 => biased exponent: 96 = -31+127 => 2^16
var SMALL_BIASED_EXP_10 = 0x43000000; // asm type annotation

// 0x3f800007 = 1065353223 => 0 01111111100 00000000000000000111 => biased exponent: 127 = 0+127 => 2^0 * (1.0000000007)
var BIASED_EXP_0 = 0x3f800007; // asm type annotation

// 0xfffff000 = 4294963200 => 1 11111111111 11111111111100000000
var HIGH_BIASED_EXP_NEG_64 = 0xfffff000; // asm type annotation

// 0x43160000 = 1128275968 => 0 10000110011 00000000000000000000 => biased exponent: 99 = -28+127 => 2^22
var SMALL_60 = 0x43160000; // asm type annotation

// 0xc3160000 = 3273056256 => 1 10000110011 00000000000000000000 => biased exponent: 99 = -28+127 => -2^22
var SMALL_NEG_60 = 0xc3160000>>>0; // asm type annotation

var HUGE = 1.0e30;
var TINY = 1.0e-30;

// -(128-log2(ovfl+.5ulp))
var OVT = 4.2995665694e-08;

// Log workspace:
var LOG_WORKSPACE = 0.0;


// MAIN //

/**
* Evaluates the exponential function for single-precision floating-point values.
*
* @param {number} x - base
* @param {number} y - exponent
* @returns {number} function value
*
* @example
* var v = powf( 2.0, 3.0 );
* // returns 8.0
*
* @example
* var v = powf( 4.0, 0.5 );
* // returns 2.0
*
* @example
* var v = powf( 100.0, 0.0 );
* // returns 1.0
*
* @example
* var v = powf( 3.1415927410125732, 5.0 );
* // returns ~306.0197
*
* @example
* var v = powf( 3.1415927410125732, -0.2 );
* // returns ~0.7954
*
* @example
* var v = powf( NaN, 3.0 );
* // returns NaN
*
* @example
* var v = powf( 5.0, NaN );
* // returns NaN
*
* @example
* var v = powf( NaN, NaN );
* // returns NaN
*/
function powf( x, y ) {
	var ahs;
	var ahx;
	var ahy;
	var ax;
	var hx;
	var hy;
	var hp;
	var lp;
	var sn;
	var y1;
	var t1;
	var t2;
	var hp;
	var lp;
	var z; // y prime
	var t;
	var j;

	x = float64ToFloat32( x );
	hx = toWordf( x );
	y = float64ToFloat32( y );
	hy = toWordf( y );

	// Special cases `y`...
	if ( y === 0.0 ) {
		return 1.0;
	}
	if ( y === 1.0 ) {
		return x;
	}
	if ( y === -1.0 ) {
		return 1.0 / x;
	}
	if ( y === 0.5 ) {
		return sqrtf( x );
	}
	if ( y === -0.5 ) {
		return 1.0 / sqrtf( x );
	}
	if ( y === 2.0 ) {
		return x * x;
	}
	if ( y === 3.0 ) {
		return x * x * x;
	}
	if ( y === 4.0 ) {
		x *= x;
		return x * x;
	}
	if ( isInfinitef( y ) ) { // y is +-inf
		return yIsInfinite( x, y );
	}

	// Special cases `x`...
	if ( hx === 0 ) {
		return xIsZero( x, y );
	}
	if ( x === 1.0 ) {
		return 1.0;
	}
	if (
		x === -1.0 &&
		isOddf( y )
	) {
		return -1.0;
	}
	if ( isInfinitef( x ) ) {
		if ( x === NINF ) {
			// `pow( 1/x, -y )`
			return powf( -0.0, -y );
		}
		if ( y < 0.0 ) {
			return 0.0;
		}
		return PINF;
	}
	if (
		x < 0.0 &&
		isInteger( y ) === false
	) {
		// Signal NaN...
		return (x-x)/(x-x); // (-1)**non-int is NaN
	}
	ax = absf( x );

	// Remove the sign bits (i.e., get absolute values):
	ahx = (hx & FLOAT32_ABS_MASK); // asm type annotation
	ahy = (hy & FLOAT32_ABS_MASK); // asm type annotation

	if ( sn && isOddf( y ) ) {
		sn = -1.0;
	} else {
		sn = 1.0;
	}
	// Case 1: `|y|` is huge

	// if |y| > 2^27
	if( ahy > HIGH_BIASED_EXP_27 ) {
	// Over- or underflow if `x` is not close to unity...
		if ( ahx < HIGH_MAX_NEAR_UNITY ) {
			// y < 0
			if ( sn === 1 ) {
				// Signal overflow...
				return sn * HUGE * HUGE;
			}
			// Signal underflow...
			return sn * TINY * TINY;
		}
		if ( ahx > BIASED_EXP_0 ) {
			// y > 0
			if ( sn === 0 ) {
				// Signal overflow...
				return sn * HUGE * HUGE;
			}
			// Signal underflow...
			return sn * TINY * TINY;
		}
		// At this point, `|1-x|` is tiny (`<= 2^-20`). Suffice to compute `log(x)` by `x - x^2/2 + x^3/3 - x^4/4`.
		t = logx( LOG_WORKSPACE, ax );
	}
	// Case 2: `|y|` is not huge...
	else {
		t = log2ax( LOG_WORKSPACE, ax, ahx );
	}
	// Split `y` into `y1 + y2` and compute `(y1+y2) * (t1+t2)`...
	ahs = fromWordf( y );
	ahs = float64ToFloat32( ahs & HIGH_BIASED_EXP_NEG_64 );
	y1 = toWordf( ahs );
	lp = float64ToFloat32(float64ToFloat32( float64ToFloat32(y-y1)*t1 ) + float64ToFloat32( y*t2 )); // eslint-disable-line max-len
	hp = float64ToFloat32( y1 * t1 );
	z = float64ToFloat32( lp + hp );
	j = fromWordf( z );


	// z > 128
	if ( j > SMALL_BIASED_EXP_10 ) {
		// Signal overflow
		return sn * HUGE * HUGE;
	}
	// z == 128
	else if ( j === SMALL_BIASED_EXP_10 ) {
		if ( (lp+OVT) > (z-hp) ) {
			// Signal overflow...
			return sn * HUGE * HUGE;
		}
	}
	// z <= -150
	else if ( (j&FLOAT32_ABS_MASK) > SMALL_60 ) {
		// Signal underflow...
		return sn * TINY * TINY;
	}
	// z == -150
	else if ( j === SMALL_NEG_60 ) {
		if( lp <= (z-hp) ) {
			// Signal underflow...
			return sn * TINY * TINY;
		}
	}
	// Compute `2^(hp+lp)`...
	z = pow2( j, hp, lp );

	return sn * z;
}


// EXPORTS //

module.exports = powf;
